void P16(std::vector<std::uint8_t>*o,std::uint16_t v){o->push_back(v);o->push_back(v>>8);} void P32(std::vector<std::uint8_t>*o,std::uint32_t v){for(int i=0;i<4;++i)o->push_back(v>>(8*i));} void P64(std::vector<std::uint8_t>*o,std::uint64_t v){for(int i=0;i<8;++i)o->push_back(v>>(8*i));} std::uint16_t U16(const std::uint8_t*p){return p[0]|std::uint16_t(p[1])<<8;} std::uint32_t U32(const std::uint8_t*p){std::uint32_t v=0;for(int i=0;i<4;++i)v|=std::uint32_t(p[i])<<(8*i);return v;} std::uint64_t U64(const std::uint8_t*p){std::uint64_t v=0;for(int i=0;i<8;++i)v|=std::uint64_t(p[i])<<(8*i);return v;} template<class A>void Put(std::vector<std::uint8_t>*o,const A&a){o->insert(o->end(),a.begin(),a.end());} template<class A>void Get(const std::uint8_t*p,A*a){std::copy_n(p,a->size(),a->begin());} template<class A>bool Nz(const A&a){return std::any_of(a.begin(),a.end(),[](auto x){return x;});} SblrTxnCommitShaV1 H(std::string_view d,const std::uint8_t*p,size_t z){std::vector<std::uint8_t>m(d.begin(),d.end());m.insert(m.end(),p,p+z);return scratchbird::core::hash::ComputeSha256Digest(m).digest;}
