std::vector<std::uint8_t> EncodeSblrTransactionCommitOptionsV1(SblrTransactionCommitOptionsV1*v){if(!v||!Nz(v->transaction_uuid)||!v->local_transaction_id||!Nz(v->admitted_handle_evidence_sha256)||(v->commit_mode!=1&&v->commit_mode!=2)||v->authority_scope<1||v->authority_scope>2||v->wait_policy<1||v->wait_policy>2)return{};std::vector<std::uint8_t>o{'T','X','C','O'};P16(&o,1);P16(&o,120);P32(&o,120);P32(&o,0);Put(&o,v->transaction_uuid);P64(&o,v->local_transaction_id);Put(&o,v->admitted_handle_evidence_sha256);o.push_back(v->commit_mode);o.push_back(v->authority_scope);o.push_back(v->wait_policy);o.insert(o.end(),5,0);P64(&o,v->deadline_monotonic_ns);v->options_sha256=H("ScratchBird.SblrTransactionCommitOptions.V1",o.data(),o.size());Put(&o,v->options_sha256);return o;}
bool DecodeSblrTransactionCommitOptionsV1(const std::uint8_t*b,std::size_t z,SblrTransactionCommitOptionsV1*out,std::string*d){if(!b||!out||z!=120||!std::equal(b,b+4,"TXCO")||U16(b+4)!=1||U16(b+6)!=120||U32(b+8)!=120||U32(b+12)||std::any_of(b+75,b+80,[](auto x){return x;})){if(d)*d="TXCO header invalid";return false;}SblrTransactionCommitOptionsV1 v;Get(b+16,&v.transaction_uuid);v.local_transaction_id=U64(b+32);Get(b+40,&v.admitted_handle_evidence_sha256);v.commit_mode=b[72];v.authority_scope=b[73];v.wait_policy=b[74];v.deadline_monotonic_ns=U64(b+80);Get(b+88,&v.options_sha256);auto c=v;auto e=EncodeSblrTransactionCommitOptionsV1(&c);if(e.size()!=z||!std::equal(e.begin(),e.end(),b))return false;*out=v;return true;}
std::vector<std::uint8_t> EncodeSblrTransactionCommitResultV1(const SblrTransactionCommitResultV1&v){if(!Nz(v.transaction_uuid)||!v.local_transaction_id||!v.commit_sequence||!Nz(v.commit_policy_snapshot_uuid)||!v.commit_policy_generation||v.lifecycle_state!=2||v.authority_scope<1||v.authority_scope>2||!v.executor_availability_generation)return{};std::vector<std::uint8_t>o{'T','X','C','R'};P16(&o,1);P16(&o,120);P32(&o,120);P32(&o,0);Put(&o,v.transaction_uuid);P64(&o,v.local_transaction_id);P64(&o,v.commit_sequence);Put(&o,v.commit_policy_snapshot_uuid);P64(&o,v.commit_policy_generation);o.push_back(v.lifecycle_state);o.push_back(v.authority_scope);o.insert(o.end(),6,0);const auto h=H("ScratchBird.SblrTransactionCommitResult.V1",o.data(),o.size());if(Nz(v.commit_evidence_sha256)&&v.commit_evidence_sha256!=h)return{};Put(&o,h);P64(&o,v.executor_availability_generation);return o;}
bool DecodeSblrTransactionCommitResultV1(const std::uint8_t*b,std::size_t z,SblrTransactionCommitResultV1*out,std::string*d){if(!b||!out||z!=120||!std::equal(b,b+4,"TXCR")||U16(b+4)!=1||U16(b+6)!=120||U32(b+8)!=120||U32(b+12)||std::any_of(b+74,b+80,[](auto x){return x;})){if(d)*d="TXCR header invalid";return false;}SblrTransactionCommitResultV1 v;Get(b+16,&v.transaction_uuid);v.local_transaction_id=U64(b+32);v.commit_sequence=U64(b+40);Get(b+48,&v.commit_policy_snapshot_uuid);v.commit_policy_generation=U64(b+64);v.lifecycle_state=b[72];v.authority_scope=b[73];Get(b+80,&v.commit_evidence_sha256);v.executor_availability_generation=U64(b+112);if(EncodeSblrTransactionCommitResultV1(v).empty())return false;*out=v;return true;}
